import { Avatar } from '@/components/avatar/Avatar';
import { Badge } from '@/components/badge/Badge';
import { Button } from '@/components/button/Button';
import { Card } from '@/components/card/Card';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
} from '@/components/table/Table';
import { ToolbarGroup } from '@/components/toolbar/Toolbar';
import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { cn } from '@/lib/utils';
import {
  type Column,
  type ExpandedState,
  type HeaderGroup,
  type Row,
  type RowSelectionState,
  type SortingState,
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { Fragment, useMemo, useState } from 'react';
import { ActionBar, FilterButton } from './action-bar';
import { emissionColumns } from './columns';
import {
  type EmissionTreeRow,
  buildEmissionTree,
  emissions,
  getEmissionLeaves,
} from './data';
import {
  CATEGORY_TITLE_LEFT,
  RAIL_STARTS,
  RAIL_WIDTHS,
  SUBCATEGORY_TITLE_LEFT,
  getPinnedClassName,
  getPinningStyles,
  titleStickyStyle,
} from './pinning';
import { ChevronCell, RailCells } from './table-rail';

function EmissionColGroup({
  columns,
}: {
  columns: Column<EmissionTreeRow>[];
}) {
  return (
    <colgroup>
      {RAIL_WIDTHS.map((width, index) => (
        <col key={`rail-${index}`} style={{ width }} />
      ))}
      {columns.map((column) => (
        <col key={column.id} style={{ width: column.getSize() }} />
      ))}
      <col />
    </colgroup>
  );
}

function EmissionHeaderRows({
  headerGroups,
}: {
  headerGroups: HeaderGroup<EmissionTreeRow>[];
}) {
  return (
    <>
      {headerGroups.map((hg) => (
        // Sticks below the category (top-0, h-9) + subcategory (top-9, h-11)
        // titles → 36 + 44 = 80px. z-[15] keeps it above source rows (pinned
        // cells z-10) but below the subcategory (z-20) and category (z-30)
        // titles. The row's z-index makes the whole header (incl. its pinned
        // cells) paint above source rows during vertical scroll.
        <TableRow
          key={hg.id}
          className="sticky top-20 z-[15] hover:bg-transparent"
        >
          <RailCells variant="vertical" />
          {hg.headers.map((header) => (
            <TableHead
              key={header.id}
              style={getPinningStyles(header.column)}
              className={cn(
                'border-b border-grayscale-opacity-300',
                getPinnedClassName(header.column),
              )}
            >
              {header.isPlaceholder
                ? null
                : flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
            </TableHead>
          ))}
          <td className="border-b border-grayscale-opacity-300 bg-white p-0" />
        </TableRow>
      ))}
    </>
  );
}

function EmissionCategoryRow({
  row,
  titleColSpan,
}: {
  row: Row<EmissionTreeRow>;
  titleColSpan: number;
}) {
  if (row.original.kind !== 'category') {
    return null;
  }

  return (
    <TableRow
      aria-expanded={row.getIsExpanded()}
      role="button"
      tabIndex={0}
      onClick={row.getToggleExpandedHandler()}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          row.toggleExpanded();
        }
      }}
      className="sticky top-0 z-30 cursor-pointer bg-[#f8f8f9] hover:bg-[#f0f0f2]"
    >
      <td
        className="sticky z-10 bg-[#f8f8f9] p-0"
        style={{ left: RAIL_STARTS[0], width: RAIL_WIDTHS[0] }}
      />
      <td
        className="sticky z-10 bg-[#f8f8f9] p-0"
        style={{ left: RAIL_STARTS[1], width: RAIL_WIDTHS[1] }}
      />
      <ChevronCell
        expanded={row.getIsExpanded()}
        leftOffset={RAIL_STARTS[2]}
        bgClassName="bg-[#f8f8f9]"
      />
      <TableCell
        colSpan={titleColSpan}
        className="h-9 overflow-visible border-r-0 bg-transparent py-0 pl-0 pr-3 text-sm font-medium text-grayscale-opacity-900"
      >
        <div
          className="flex items-center gap-2 overflow-hidden whitespace-nowrap pr-3"
          style={titleStickyStyle(CATEGORY_TITLE_LEFT)}
        >
          <Badge variant="info" type="text" size="md">
            ISO
          </Badge>
          <Avatar fallback="" size="xs" color="tiffany" />
          <span className="truncate">{row.original.title}</span>
          <span className="ml-auto text-sm font-normal tabular-nums text-grayscale-opacity-700">
            {getEmissionLeaves(row.original).length}
          </span>
        </div>
      </TableCell>
    </TableRow>
  );
}

function EmissionSubcategoryRow({
  row,
  titleColSpan,
}: {
  row: Row<EmissionTreeRow>;
  titleColSpan: number;
}) {
  if (row.original.kind !== 'subcategory') {
    return null;
  }

  return (
    <TableRow
      aria-expanded={row.getIsExpanded()}
      role="button"
      tabIndex={0}
      onClick={row.getToggleExpandedHandler()}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          row.toggleExpanded();
        }
      }}
      className="sticky top-9 z-20 cursor-pointer bg-white hover:bg-grayscale-opacity-100"
    >
      <RailCells
        variant="branch"
        trailingCell={
          <ChevronCell
            expanded={row.getIsExpanded()}
            leftOffset={RAIL_STARTS[3]}
          />
        }
      />
      <TableCell
        colSpan={titleColSpan}
        className="h-11 overflow-visible border-r-0 bg-transparent py-0 pl-0 pr-3 text-sm font-medium text-grayscale-opacity-800"
      >
        <div
          className="flex items-center gap-2 overflow-hidden whitespace-nowrap pr-3"
          style={titleStickyStyle(SUBCATEGORY_TITLE_LEFT)}
        >
          <Badge variant="info" type="text" size="md">
            ISO
          </Badge>
          <Avatar fallback="" size="xs" color="tiffany" />
          <span className="truncate">{row.original.title}</span>
          <span className="ml-auto text-sm font-normal tabular-nums text-grayscale-opacity-700">
            {getEmissionLeaves(row.original).length}
          </span>
        </div>
      </TableCell>
    </TableRow>
  );
}

function EmissionSourceRow({ row }: { row: Row<EmissionTreeRow> }) {
  return (
    <TableRow>
      <RailCells variant="vertical" />
      {row.getVisibleCells().map((cell) => {
        const pinStyle = getPinningStyles(cell.column);
        const pinClass = getPinnedClassName(cell.column);

        if (cell.column.id === 'id') {
          return (
            <TableHead
              key={cell.id}
              scope="row"
              style={pinStyle}
              className={cn(
                'h-11 border-b border-grayscale-opacity-300 bg-transparent px-3 py-1 align-middle font-normal text-grayscale-opacity-800',
                pinClass,
              )}
            >
              {flexRender(
                cell.column.columnDef.cell,
                cell.getContext(),
              )}
            </TableHead>
          );
        }

        return (
          <TableCell
            key={cell.id}
            style={pinStyle}
            className={cn(
              'border-b border-grayscale-opacity-300 bg-transparent',
              pinClass,
            )}
          >
            {flexRender(
              cell.column.columnDef.cell,
              cell.getContext(),
            )}
          </TableCell>
        );
      })}
      <td className="border-b border-grayscale-opacity-300 p-0" />
    </TableRow>
  );
}

export function DataTableGroup02() {
  const [sorting, setSorting] = useState<SortingState>([]);
  // `true` expands every row by default (vs `{}` which collapses all).
  const [expanded, setExpanded] = useState<ExpandedState>(true);
  const [rowSelection, setRowSelection] = useState<RowSelectionState>(
    {},
  );
  const data = useMemo(() => buildEmissionTree(emissions), []);
  const table = useReactTable({
    data,
    columns: emissionColumns,
    state: { expanded, rowSelection, sorting },
    initialState: {
      columnPinning: { left: ['select', 'id'] },
    },
    enableRowSelection: true,
    onExpandedChange: setExpanded,
    onRowSelectionChange: setRowSelection,
    onSortingChange: setSorting,
    getSubRows: (row) =>
      row.kind === 'source' ? undefined : row.subRows,
    getCoreRowModel: getCoreRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    getSortedRowModel: getSortedRowModel(),
  });
  const visibleColumns = table.getVisibleLeafColumns();
  // Total cols = 4 rail tracks + data cols + 1 trailing fill col.
  // Category title spans everything to the right of the chevron (col 3).
  // Subcategory title spans everything to the right of its chevron (col 4).
  const categoryTitleColSpan = visibleColumns.length + 2;
  const subcategoryTitleColSpan = visibleColumns.length + 1;

  return (
    <Card className="w-full max-w-[1408px]">
      <ActionBar
        searchPlaceholder="搜尋"
        left={
          <ToolbarGroup>
            <FilterButton>負責人</FilterButton>
            <FilterButton>審核人</FilterButton>
          </ToolbarGroup>
        }
        right={
          <ToolbarGroup>
            <FilterButton>分群:排放源</FilterButton>
            <FilterButton>顯示欄位</FilterButton>
            <FilterButton>審核:開啟</FilterButton>
            <Button variant="default" theme="default">
              填報欄位名稱
            </Button>
            <Button variant="default" theme="primary">
              新增
              <ChevronDownIcon data-icon="inline-end" />
            </Button>
          </ToolbarGroup>
        }
      />
      <Table
        className="table-fixed border-separate border-spacing-0"
        containerClassName="max-h-[560px] overflow-auto"
        style={{ minWidth: 1408 }}
      >
        <EmissionColGroup columns={visibleColumns} />
        {table
          .getRowModel()
          .rows.filter((row) => row.depth === 0)
          .map((categoryRow) => (
            <TableBody key={categoryRow.id}>
              <EmissionCategoryRow
                row={categoryRow}
                titleColSpan={categoryTitleColSpan}
              />
              {categoryRow.getIsExpanded() &&
                categoryRow.subRows.map((subcategoryRow) => (
                  <Fragment key={subcategoryRow.id}>
                    <EmissionSubcategoryRow
                      row={subcategoryRow}
                      titleColSpan={subcategoryTitleColSpan}
                    />
                    {subcategoryRow.getIsExpanded() && (
                      <>
                        <EmissionHeaderRows
                          headerGroups={table.getHeaderGroups()}
                        />
                        {subcategoryRow.subRows.map((sourceRow) => (
                          <EmissionSourceRow
                            key={sourceRow.id}
                            row={sourceRow}
                          />
                        ))}
                      </>
                    )}
                  </Fragment>
                ))}
            </TableBody>
          ))}
      </Table>
    </Card>
  );
}

import { Button } from '@/components/button/Button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/dropdown-menu/DropdownMenu';
import { SearchBar } from '@/components/search-bar/SearchBar';
import { Toolbar, ToolbarSpacer } from '@/components/toolbar/Toolbar';
import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { EllipsisIcon } from '@/icons/EllipsisIcon';
import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';

export function ActionBar({
  searchPlaceholder,
  left,
  right,
  raised = false,
  minWidthClassName,
}: {
  searchPlaceholder: string;
  left?: ReactNode;
  right?: ReactNode;
  raised?: boolean;
  minWidthClassName?: string;
}) {
  return (
    <Toolbar
      size="sm"
      className={cn(
        'h-12 flex-nowrap gap-6 overflow-x-auto overflow-y-hidden rounded bg-white px-3 py-2',
        '[&_[data-slot=toolbar-group]]:shrink-0',
        raised && 'shadow-emphasis',
        minWidthClassName,
      )}
    >
      <SearchBar
        placeholder={searchPlaceholder}
        width="200px"
        className="h-8 shrink-0 rounded border-none"
      />
      {left}
      <ToolbarSpacer />
      {right}
    </Toolbar>
  );
}

export function FilterButton({ children }: { children: string }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            theme="default"
            className="h-8 rounded-full px-3 font-normal"
          >
            {children}
            <ChevronDownIcon data-icon="inline-end" />
          </Button>
        }
      />
      <DropdownMenuContent>
        <DropdownMenuItem>全部</DropdownMenuItem>
        <DropdownMenuItem>已指派</DropdownMenuItem>
        <DropdownMenuItem>未指派</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export function MoreButton() {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            aria-label="更多操作"
            variant="text"
            size="icon-md"
            theme="default"
          >
            <EllipsisIcon />
          </Button>
        }
      />
      <DropdownMenuContent align="start">
        <DropdownMenuGroup>
          <DropdownMenuItem>編輯</DropdownMenuItem>
          <DropdownMenuItem>複制</DropdownMenuItem>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>刪除</DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { Avatar } from '@/components/avatar/Avatar';
import { Checkbox } from '@/components/checkbox/Checkbox';
import { Switch } from '@/components/switch/Switch';
import { Tag } from '@/components/tag/Tag';
import type { ColumnDef } from '@tanstack/react-table';
import { MoreButton } from './action-bar';
import type { EmissionTreeRow } from './data';
import { DataTableColumnHeader } from './data-table-column-header';

export const emissionColumns: ColumnDef<EmissionTreeRow>[] = [
  {
    id: 'select',
    header: ({ table }) => (
      <Checkbox
        aria-label="Select all"
        checked={table.getIsAllPageRowsSelected()}
        indeterminate={table.getIsSomePageRowsSelected()}
        onCheckedChange={(value) =>
          table.toggleAllPageRowsSelected(Boolean(value))
        }
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        aria-label={`Select row ${row.original.id}`}
        checked={row.getIsSelected()}
        onCheckedChange={(value) =>
          row.toggleSelected(Boolean(value))
        }
      />
    ),
    size: 40,
    enableSorting: false,
  },
  {
    accessorKey: 'id',
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="序" />
    ),
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.id : null,
    size: 38,
    enableSorting: false,
  },
  {
    id: 'source',
    accessorFn: (row) => (row.kind === 'source' ? row.source : ''),
    header: ({ column }) => (
      <DataTableColumnHeader column={column} title="排放源" />
    ),
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.source : null,
    size: 164,
  },
  {
    id: 'formula',
    accessorFn: (row) => (row.kind === 'source' ? row.formula : ''),
    header: '係數名稱',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.formula : null,
    size: 312,
    enableSorting: false,
  },
  {
    id: 'count',
    accessorFn: (row) => (row.kind === 'source' ? row.count : 0),
    header: '據點數',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.count : null,
    size: 66,
    enableSorting: false,
  },
  {
    id: 'owner',
    accessorFn: (row) => (row.kind === 'source' ? row.owner : ''),
    header: '負責人',
    cell: ({ row }) =>
      row.original.kind !== 'source' ? null : row.original.owner ===
        '未指派' ? (
        <Avatar fallback="?" size="sm" color="orange" />
      ) : (
        <Avatar
          fallback={row.original.owner}
          name={row.original.owner}
          size="sm"
          color="tiffany"
        />
      ),
    size: 102,
    enableSorting: false,
  },
  {
    id: 'reviewer',
    accessorFn: (row) => (row.kind === 'source' ? row.reviewer : ''),
    header: '審核人',
    cell: ({ row }) =>
      row.original.kind !== 'source' ? null : row.original
          .reviewer === '未指派' ? (
        <Avatar fallback="?" size="sm" color="orange" />
      ) : (
        <Avatar
          fallback={row.original.reviewer}
          name={row.original.reviewer}
          size="sm"
          color="tiffany"
        />
      ),
    size: 102,
    enableSorting: false,
  },
  {
    id: 'template',
    accessorFn: (row) => (row.kind === 'source' ? row.template : ''),
    header: '填報樣板',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.template : null,
    size: 116,
    enableSorting: false,
  },
  {
    id: 'reference',
    accessorFn: (row) =>
      row.kind === 'source' ? row.reference : null,
    header: '引用排放源',
    cell: ({ row }) =>
      row.original.kind === 'source' ? row.original.reference : null,
    size: 104,
    enableSorting: false,
  },
  {
    id: 'tag',
    accessorFn: (row) => (row.kind === 'source' ? row.tag : null),
    header: '標籤',
    cell: ({ row }) =>
      row.original.kind === 'source' && row.original.tag ? (
        <Tag color="gold" colorVariant="tint">
          {row.original.tag}
        </Tag>
      ) : null,
    size: 76,
    enableSorting: false,
  },
  {
    id: 'significant',
    header: '重大',
    cell: () => null,
    size: 48,
    enableSorting: false,
  },
  {
    id: 'quantified',
    header: '量化',
    cell: ({ row }) =>
      row.original.kind === 'source' ? (
        <Switch defaultChecked={row.original.quantified} />
      ) : null,
    size: 68,
    enableSorting: false,
  },
  {
    id: 'note',
    header: '備註',
    cell: () => null,
    size: 48,
    enableSorting: false,
  },
  {
    id: 'actions',
    header: '',
    cell: () => <MoreButton />,
    size: 36,
    enableSorting: false,
  },
];

import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { ChevronUpIcon } from '@/icons/ChevronUpIcon';
import { cn } from '@/lib/utils';
import type { Column } from '@tanstack/react-table';
import type { ReactNode } from 'react';

export interface DataTableColumnHeaderProps<TData, TValue> {
  column: Column<TData, TValue>;
  title: ReactNode;
  className?: string;
}

export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  if (!column.getCanSort()) {
    return <span className={className}>{title}</span>;
  }

  const sort = column.getIsSorted();

  return (
    <button
      type="button"
      data-slot="data-table-column-header"
      data-sort={sort || undefined}
      onClick={column.getToggleSortingHandler()}
      className={cn(
        'inline-flex cursor-pointer items-center gap-1 font-normal text-grayscale-opacity-800 transition-colors hover:text-grayscale-opacity-900 focus-visible:shadow-focus-primary focus-visible:outline-none',
        className,
      )}
    >
      <span>{title}</span>
      <span
        aria-hidden="true"
        className="inline-flex size-4 items-center justify-center text-grayscale-opacity-500"
      >
        {sort === 'desc' ? (
          <ChevronDownIcon className="size-3.5" />
        ) : sort === 'asc' ? (
          <ChevronUpIcon className="size-3.5" />
        ) : (
          <span className="relative inline-flex h-3 w-3 flex-col items-center justify-between leading-none">
            <ChevronUpIcon className="size-2" />
            <ChevronDownIcon className="size-2" />
          </span>
        )}
      </span>
    </button>
  );
}

import type { Column } from '@tanstack/react-table';
import type { CSSProperties } from 'react';
import type { EmissionTreeRow } from './data';

export const RAIL_WIDTHS = [4, 28, 24, 24] as const;
export const RAIL_STARTS = [0, 4, 32, 56] as const; // cumulative left of each rail col
export const RAIL_OFFSET = RAIL_WIDTHS.reduce((sum, w) => sum + w, 0); // 80
export const CATEGORY_TITLE_LEFT = RAIL_STARTS[3]; // chevron in col 3, title starts at col 4
export const SUBCATEGORY_TITLE_LEFT = RAIL_OFFSET; // chevron in col 4, title starts at col 5

export function titleStickyStyle(leftOffset: number): CSSProperties {
  return {
    position: 'sticky',
    left: leftOffset,
    width: `min(${1408 - leftOffset}px, calc(100vw - ${leftOffset + 48}px))`,
  };
}

export function getPinningStyles(
  column: Column<EmissionTreeRow>,
): CSSProperties {
  if (column.getIsPinned() !== 'left') {
    return {};
  }

  return {
    position: 'sticky',
    left: `${RAIL_OFFSET + column.getStart('left')}px`,
    width: column.getSize(),
    zIndex: 10,
    boxShadow: column.getIsLastColumn('left')
      ? 'inset -1px 0 0 var(--grayscale-opacity-300)'
      : undefined,
  };
}

export function getPinnedClassName(column: Column<EmissionTreeRow>) {
  // Pinned cells need a solid bg so scrolling content doesn't bleed through.
  // We lose the TR hover bg for these cells — acceptable for identity columns.
  return column.getIsPinned() === 'left' ? 'bg-white' : undefined;
}

import { ChevronDownIcon } from '@/icons/ChevronDownIcon';
import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';
import { RAIL_STARTS, RAIL_WIDTHS } from './pinning';

export function RailVertical() {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-border"
    />
  );
}

export function RailBranch() {
  return (
    <span
      aria-hidden="true"
      className="pointer-events-none absolute right-0 top-0 h-[22px] w-3 rounded-bl-lg border-b border-l border-border"
    />
  );
}

export function RailCells({
  variant,
  trailingCell,
  bgClassName = 'bg-white',
}: {
  variant: 'vertical' | 'branch';
  trailingCell?: ReactNode;
  bgClassName?: string;
}) {
  const cellClass = cn('sticky z-10 p-0', bgClassName);
  return (
    <>
      <td
        className={cellClass}
        style={{ left: RAIL_STARTS[0], width: RAIL_WIDTHS[0] }}
      />
      <td
        className={cellClass}
        style={{ left: RAIL_STARTS[1], width: RAIL_WIDTHS[1] }}
      />
      <td
        className={cellClass}
        style={{ left: RAIL_STARTS[2], width: RAIL_WIDTHS[2] }}
      >
        <RailVertical />
        {variant === 'branch' && <RailBranch />}
      </td>
      {trailingCell ?? (
        <td
          className={cellClass}
          style={{ left: RAIL_STARTS[3], width: RAIL_WIDTHS[3] }}
        />
      )}
    </>
  );
}

export function ChevronCell({
  expanded,
  leftOffset,
  bgClassName = 'bg-white',
}: {
  expanded: boolean;
  leftOffset: number;
  bgClassName?: string;
}) {
  return (
    <td
      className={cn('sticky z-10 p-0 text-center', bgClassName)}
      style={{ left: leftOffset, width: 24 }}
    >
      <ChevronDownIcon
        className={cn(
          'mx-auto size-3 text-grayscale-opacity-700 transition-transform',
          !expanded && '-rotate-90',
        )}
      />
    </td>
  );
}
